<?php /** The requester card and the followers/CCs. Data: t, facts, requester, internals, work, own, here */ $id = (int) $facts['ticket_id']; $r = $requester; $hidden = csrf_field() . '<input type="hidden" name="ticket" value="' . $id . '"><input type="hidden" name="return_to" value="' . e($here) . '">'; ?>
<div class="card mb-3" id="ticket-requester"><div class="card-header"><h5 class="card-title mb-0">Requester</h5><?php if ($internals): ?><?= hx_link(with_back('/requesters/' . (int) $r['requester_id'] . '/edit', $here), 'Edit', 'fs-12', 'id="ticket-requester-edit"') ?><?php endif; ?></div><div class="card-body">
    <div class="fw-semibold"><?= $internals ? hx_link(with_back('/requesters/' . (int) $r['requester_id'], $here), e($r['display_name']), 'text-dark', 'id="ticket-requester-name"') : '<span id="ticket-requester-name">' . e($r['display_name']) . '</span>' ?>
        <?php if ($r['kind'] === 'external'): ?><span class="badge bg-soft-primary text-primary"><i class="feather-globe"></i> external</span><?php elseif ($r['kind'] === 'agent'): ?><span class="badge bg-soft-info text-info"><i class="feather-cpu"></i> agent</span><?php else: ?><span class="badge bg-soft-secondary text-secondary">member</span><?php endif; ?></div>
    <?php if ($r['organization_id']): ?><div class="fs-12"><?= $internals ? hx_link(with_back('/organizations/' . (int) $r['organization_id'], $here), e($r['organization_name'])) : e($r['organization_name']) ?><?= $r['support_tier'] ? ' <span class="badge bg-soft-primary text-primary">' . e($r['support_tier']) . '</span>' : '' ?></div><?php endif; ?>
    <?php if ($internals && ($r['email'] || $r['phone'])): ?><div class="fs-12 text-muted" id="ticket-requester-contact"><?= e($r['email'] ?? '') ?><?= $r['email'] && $r['phone'] ? ' · ' : '' ?><?= e($r['phone'] ?? '') ?></div><?php endif; ?>
    <?php if ($internals && $r['notes']): ?><div class="fs-12 border-top mt-2 pt-2" id="ticket-requester-notes"><span class="text-muted">Notes:</span> <?= nl2br(e($r['notes'])) ?></div><?php endif; ?>
    <?php if ($internals && count($r['last_tickets']) > 1): ?><div class="fs-12 border-top mt-2 pt-2" id="ticket-requester-recent"><div class="text-muted">Recent</div><?php foreach ($r['last_tickets'] as $x): if ((int) $x['ticket_id'] === $id) { continue; } ?><div><?= hx_link(with_back('/tickets/' . (int) $x['ticket_id'], $here), e($x['number']) . ' ' . e($x['subject'])) ?> <span class="badge bg-<?= e($x['status_color']) ?>"><?= e($x['status_label']) ?></span></div><?php endforeach; ?></div><?php endif; ?>
    <div class="border-top mt-2 pt-2">
        <div class="fs-12 text-muted">CCs and followers</div>
        <div class="d-flex flex-wrap gap-1 mb-1" id="ticket-followers">
            <?php foreach ($t['followers'] as $f): $name = $f['member_name'] ?? $f['requester_name']; $isCc = $f['kind'] === 'cc'; $mayRemove = $isCc ? $work : ($work || $f['member_id'] === (int) current_member_id()); ?>
                <?php if ($mayRemove): ?><form method="post" action="/tickets/<?= $isCc ? 'cc-remove' : 'unfollow' ?>.php" hx-post="/tickets/<?= $isCc ? 'cc-remove' : 'unfollow' ?>.php" hx-target="#flash" class="d-inline"><?= $hidden ?><input type="hidden" name="<?= $isCc ? 'cc' : 'member' ?>" value="<?= $isCc ? e((string) ($f['requester_id'] ?? ('m' . $f['member_id']))) : (int) $f['member_id'] ?>"><button type="submit" class="badge bg-soft-<?= $isCc ? 'primary text-primary' : 'secondary text-secondary' ?> border-0" id="ticket-follower-<?= e($f['kind']) ?>-<?= (int) ($f['member_id'] ?? $f['requester_id']) ?>"><?= $isCc ? 'cc ' : '' ?><?= e($name) ?> <i class="feather-x"></i></button></form>
                <?php else: ?><span class="badge bg-soft-<?= $isCc ? 'primary text-primary' : 'secondary text-secondary' ?>" id="ticket-follower-<?= e($f['kind']) ?>-<?= (int) ($f['member_id'] ?? $f['requester_id']) ?>"><?= $isCc ? 'cc ' : '' ?><?= e($name) ?></span><?php endif; ?>
            <?php endforeach; ?>
        </div>
        <?php if ($work || $own): ?><form method="post" action="/tickets/cc.php" hx-post="/tickets/cc.php" hx-target="#flash" class="input-group mb-1" id="ticket-cc-form"><?= $hidden ?><input type="email" name="cc" id="ticket-cc-form-field-cc" class="form-control btn-touch" placeholder="cc an email" required><button type="submit" class="btn btn-light btn-touch" id="ticket-cc-form-add-btn"><i class="feather-plus"></i></button></form><?php endif; ?>
        <?php $following = array_filter($t['followers'], static fn (array $f): bool => $f['kind'] === 'follower' && $f['member_id'] === (int) current_member_id()); ?>
        <?php if ($following === []): ?><form method="post" action="/tickets/follow.php" hx-post="/tickets/follow.php" hx-target="#flash"><?= $hidden ?><button type="submit" class="btn btn-light btn-sm btn-touch w-100" id="ticket-follow-btn"><i class="feather-eye me-1"></i>Follow</button></form><?php endif; ?>
    </div>
</div></div>
